      "req": "REQ-2234-N2",
      "verdict": "cannot_determine",
      "confidence_basis": "tests.fail_without_fix was not run, so it cannot be confirmed that the new tests fail without the fix; the full suite shows no regression in pre-existing tests (the two failures are new tests and none also fail on base).",
      "evidence": [
        {"kind": "check", "id": "tests.fail_without_fix", "status": "error"},
        {"kind": "check", "id": "tests.full_suite", "status": "fail"}
      ]
    }
  ],
